 {
 	loader_path path_impl;
+	size_t length;

 	if (tag == NULL || path == NULL)
 	{
 		return 1;
 	}

-	strncpy(path_impl, path, LOADER_PATH_SIZE - 1);
+	length = strnlen(path, LOADER_PATH_SIZE);
+
+	if (length >= LOADER_PATH_SIZE)
+	{
