+TEST_F(metacall_path_overflow_test, ExecutionPathOverflow)
+{
+	ASSERT_EQ((int)0, (int)metacall_initialize());
+
+	std::string path_fit(LOADER_PATH_SIZE - 1, 'a');
+	EXPECT_EQ(metacall_execution_path("mock", path_fit.c_str()), 0);
+
